    // Step 1: Get the left child of the node
    TreeNode<T> leftChild = node.left;

    // Step 2: Promote the right child of the left child to be the left child of the node
    node.left = leftChild.right;

    // Step 3: Make the left child of the node the right child of the left child of the node
    leftChild.right = node;

    // Step 4: Return the new parent of the node
    return leftChild;
}

