public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Check if the input graph is valid
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Input graph or result map is null");
    }

    // Get the number of vertices in the input graph
    int numVertices = target.getNumVertices();

    // Create a new graph with the same number of vertices as the input graph
    Graph<V, E> newGraph = new Graph<>(numVertices);

    // Iterate over the vertices in the input graph
    for (int i = 0; i < numVertices; i++) {
        // Get the current vertex
        V vertex = target.getVertex(i);

        // Check if the vertex is in the result map
        if (resultMap.containsKey(vertex)) {
            // Get the corresponding result vertex
            V resultVertex = resultMap.get(vertex);

            // Add the edge between the current vertex and the result vertex
            newGraph.addEdge(vertex, resultVertex);
        }
    }

    // Return the new graph
    return newGraph;
}

