public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("str cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("session cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("lb cannot be null");
    }

    int strLen = str.length();
    int i = 0;
    while (i < strLen) {
        int c = str.charAt(i);
        if (c <= 0x007F) {
            lb.putByte((byte) c);
        } else if (c > 0x07FF) {
            lb.putByte((byte) (0xE0 | c >> 12 & 0x0F));
            lb.putByte((byte) (0x80 | c >> 6 & 0x3F));
            lb.putByte((byte) (0x80 | c & 0x3F));
        } else {
            lb.putByte((byte) (0xC0 | c >> 6 & 0x1F));
            lb.putByte((byte) (0x80 | c & 0x3F));
        }
        i++;
    }
    return lb;
}

