public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the center of the box along the x-axis
    double centerX = box.getMinX() + (box.getMaxX() - box.getMinX()) / 2;

    // Create two new boxes, one with the left half of the original box and the other with the right half
    Box2D leftBox = new Box2D(box.getMinX(), centerX, box.getMinY(), box.getMaxY());
    Box2D rightBox = new Box2D(centerX, box.getMaxX(), box.getMinY(), box.getMaxY());

    // Return a pair with the two resulting boxes
    return new Pair<>(leftBox, rightBox);
}

private void enlarge(final int size) {
    // Check if the new size is valid
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }

    // Calculate the new capacity
    int newCapacity = this.capacity + size;

    // Check if the new capacity is valid
    if (newCapacity < 0) {
        throw new IllegalStateException("New capacity must be non-negative");
    }

    // Create a new array with the new capacity
    byte[] newArray = new byte[newCapacity];

    // Copy the old data to the new array
    System.arraycopy(this.array, 0, newArray, 0, this.capacity);

    // Set the new array and capacity
    this.array = newArray;
    this.capacity = newCapacity;
}

