public String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
    // Check if the constant pool entry index is valid
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }

    // Check if the char buffer is large enough
    if (charBuffer.length < 1024) {
        throw new IllegalArgumentException("Char buffer is too small: " + charBuffer.length);
    }

    // Read the CONSTANT_Utf8 entry
    int entryOffset = classFileBuffer[constantPoolEntryIndex];
    int entryLength = classFileBuffer[constantPoolEntryIndex + 1];
    if (entryOffset < 0 || entryLength < 0) {
        throw new IllegalStateException("Invalid CONSTANT_Utf8 entry offset or length: " + entryOffset + ", " + entryLength);
    }

    // Read the string from the char buffer
    int stringOffset = entryOffset + 2;
    int stringLength = entryLength - 2;
    if (stringOffset < 0 || stringLength < 0) {
        throw new IllegalStateException("Invalid string offset or length: " + stringOffset + ", " + stringLength);
    }
    String string = new String(charBuffer, stringOffset, stringLength);

    return string;
}

