    // Step 2: Iterate over the circulator until we find a node that satisfies the predicate or reach the stop node
    while (circulator.hasNext() && !predicate.test(circulator.next())) {
        // Step 3: If we reach the stop node, return the circulator
        if (circulator.next() == stop) {
            return circulator;
        }
    }

