public int addConstantNameAndType(String name, String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPool.size(); i++) {
        ConstantPoolItem item = constantPool.get(i);
        if (item instanceof ConstantNameAndType) {
            ConstantNameAndType constantNameAndType = (ConstantNameAndType) item;
            if (constantNameAndType.getName().equals(name) && constantNameAndType.getDescriptor().equals(descriptor)) {
                // The constant pool already contains a similar item, return its index
                return i;
            }
        }
    }

    // Create a new ConstantNameAndType item and add it to the constant pool
    ConstantNameAndType constantNameAndType = new ConstantNameAndType(name, descriptor);
    constantPool.add(constantNameAndType);

    // Return the index of the new item in the constant pool
    return constantPool.size() - 1;
}

