private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Check if the minimum label is valid
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid minimum label: " + minLabel);
    }

    // Get the bucket with the minimum label
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);

    // Check if the bucket is not empty
    if (minBucket.isEmpty()) {
        throw new IllegalStateException("Cannot reload from an empty bucket");
    }

    // Move all vertices from the minimum label bucket to the bucket with label 0
    for (int vertex : minBucket) {
        bucketsByLabel.get(0).add(vertex);
        labels.set(vertex, 0);
    }

    // Clear the minimum label bucket
    minBucket.clear();
}

