private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize variables
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;

    // Iterate through the list in reverse order
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Compute the suffix sum for the current element
        int suffixSumForCurrentElement = 0;
        for (int j = i; j < bounds.size(); j++) {
            suffixSumForCurrentElement += bounds.get(j);
        }

        // Add the suffix sum to the list
        suffixSum.add(suffixSumForCurrentElement);

        // Update the total sum
        totalSum += suffixSumForCurrentElement;
    }

    // Return the computed suffix sum list and the total sum
    return new Pair<>(suffixSum, totalSum);
}

