            if (vertex.equals(edge.getSecond())) {
                continue;
            }
            List<Pair<Integer, Integer>> separators = computeMinimalSeparators(edge, vertex);
            minimalSeparators.addAll(separators);
        }
        separatorList.add(new Pair<>(minimalSeparators, edge));
    }

    return separatorList;
}

