public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the given vertices form a complete subgraph
    if (vertices.size() < 2) {
        return false;
    }

    // Create a new graph with the given vertices as vertices and all edges between them
    Graph<V, E> subgraph = new Graph<>(vertices);
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 != v2) {
                subgraph.addEdge(v1, v2);
            }
        }
    }

    // Check if the subgraph is complete
    return subgraph.isComplete();
}

public List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    for (K key : keys) {
        int lowerBound = 0;
        for (int i = 0; i < keys.size(); i++) {
            if (keys.get(i).compareTo(key) > 0) {
                lowerBound++;
            }
        }
        lowerBounds.add(lowerBound);
    }
    return lowerBounds;
}

private void pop(final String descriptor) {
    // Check if the descriptor is a type descriptor
    if (descriptor.startsWith("L") && descriptor.endsWith(";")) {
        // Pop the type from the output frame stack
        outputFrameStack.pop();
    } else if (descriptor.startsWith("(") && descriptor.endsWith(")")) {
        // Pop the method's argument types from the output frame stack
        int numArgs = descriptor.length() - 2;
        for (int i = 0; i < numArgs; i++) {
            outputFrameStack.pop();
        }
    } else {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
}

