public static boolean substringMatch(String str, int index, String substring) {
    if (str == null || substring == null) {
        return false;
    }

    int substringLength = substring.length();
    int strLength = str.length();
    if (index > strLength - substringLength) {
        return false;
    }

    for (int i = 0; i < substringLength; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }

    return true;
}

protected void append(LoggingEvent event) {
    // Check if there are any connected clients
    if (connectedClients.isEmpty()) {
        // If there are no connected clients, do not attempt to write the message
        return;
    }

    // Create a new thread to handle the message writing
    Thread writingThread = new Thread(() -> {
        // Iterate over each connected client
        for (Client client : connectedClients) {
            // Write the message to the client
            client.write(event.getMessage());
        }
    });

    // Start the writing thread
    writingThread.start();
}

